    "stem": "A 24-year-old man attends the general practice consultative suite for Australian Medical Council clinical examination review with clinical findings indicative of Hepatitis B Chronic Infection Antiviral Eligibility Criteria. Clinical examination and investigative review confirm tenofovir or entecavir for elevated ALT > 2x ULN and HBV DNA > 20,000 IU/mL or significant fibrosis. Vitals reveal blood pressure of 137/85 mm Hg, heart rate of 93/min, respiratory rate of 19/min, and temperature of 38.1C (98.6F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of hepatitis b chronic infection antiviral eligibility criteria. Which of the following is the most appropriate next step in clinical management according to Australian Therapeutic Guidelines (eTG) and national consensus guidelines?",
    "options": [
      {
        "text": "Routine abdominal computed tomography with intravenous contrast",
        "correct": false,
        "explanation": "Incorrect: Immediate cross-sectional contrast imaging without baseline renal function assessment or targeted hemodynamic evaluation is inappropriate."
      },
      {
        "text": "Oral bisphosphonate administration during active hypocalcemia",
        "correct": false,
        "explanation": "Incorrect: Potent osteoclast inhibition in hypocalcemic states triggers life-threatening cardiac arrhythmias, tetany, and laryngeal spasm."
      },
      {
        "text": "Oral methotrexate therapy without concurrent folic acid supplementation",
        "correct": false,
        "explanation": "Incorrect: Methotrexate without folate rescue markedly elevates the frequency of severe mucositis, gastrointestinal toxicity, and bone marrow failure."
      },
      {
        "text": "Tenofovir or entecavir for elevated ALT > 2x ULN and HBV DNA > 20,000 IU/mL or significant fibrosis",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is tenofovir or entecavir for elevated ALT > 2x ULN and HBV DNA > 20,000 IU/mL or significant fibrosis. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Reassurance and discharge with routine outpatient review in six months",
        "correct": false,
        "explanation": "Incorrect: Delaying intervention in an acutely decompensated or high-risk condition risks rapid irreversible clinical deterioration and preventable complications."
      }
    ],
